import { VariantLayout } from './variant-layout.js';
import { html, css } from 'lit';
import { isMobileOrTablet } from '../utils.js';
import { EVENT_MERCH_CARD_ACTION_MENU_TOGGLE } from '../constants.js';
import { CSS } from './catalog.css.js';

export const CATALOG_AEM_FRAGMENT_MAPPING = {
    cardName: { attribute: 'name' },
    badge: true,
    ctas: { slot: 'footer', size: 'm' },
    description: { tag: 'div', slot: 'body-xs' },
    mnemonics: { size: 'l' },
    prices: { tag: 'h3', slot: 'heading-xs' },
    shortDescription: {
        tag: 'div',
        slot: 'action-menu-content',
        attributes: { tabindex: '0' },
    },
    size: ['wide', 'super-wide'],
    title: { tag: 'h3', slot: 'heading-xs' },
};

export class Catalog extends VariantLayout {
    constructor(card) {
        super(card);
    }

    get actionMenu() {
        return this.card.shadowRoot.querySelector('.action-menu');
    }

    get actionMenuContentSlot() {
        return this.card.shadowRoot.querySelector(
            'slot[name="action-menu-content"]',
        );
    }

    get slottedContent() {
        return this.card.querySelector('[slot="action-menu-content"]');
    }

    setIconVisibility(visible) {
        if (this.slottedContent) {
            if (isMobileOrTablet() && this.card.actionMenu) return;
            this.actionMenu?.classList.toggle('invisible', !visible);
            this.actionMenu?.classList.toggle('always-visible', visible);
        }
    }

    setMenuVisibility(open) {
        this.actionMenuContentSlot?.classList.toggle('hidden', !open);
        this.setAriaExpanded(this.actionMenu, open.toString());
        if (open) {
            this.dispatchActionMenuToggle();
            setTimeout(() => {
                const firstLink = this.slottedContent?.querySelector('a');
                if (firstLink) firstLink.focus();
            }, 0);
        }
    }

    isMenuOpen() {
        return !this.actionMenuContentSlot?.classList.contains('hidden');
    }

    renderLayout() {
        return html` <div class="body">
                <div class="top-section">
                    <slot name="icons"></slot> ${this.badge}
                    <div
                        class="action-menu
                ${this.slottedContent
                            ? isMobileOrTablet() && this.card.actionMenu
                                ? 'always-visible'
                                : 'invisible'
                            : 'hidden'}"
                        @click="${this.toggleActionMenu}"
                        @keypress="${this.toggleActionMenu}"
                        @focus="${this.showActionMenuOnHover}"
                        @blur="${this.hideActionMenuOnBlur}"
                        tabindex="0"
                        aria-expanded="false"
                        aria-hidden="false"
                        role="button"
                    >
                        ${this.card.actionMenuLabel} - ${this.card.title}
                    </div>
                </div>
                <slot
                    name="action-menu-content"
                    class="action-menu-content
            ${!this.card.actionMenuContent ? 'hidden' : ''}"
                    >${this.card.actionMenuContent}
                </slot>
                <slot name="heading-xs"></slot>
                <slot name="heading-m"></slot>
                <slot name="body-xxs"></slot>
                ${!this.promoBottom
                    ? html`<slot name="promo-text"></slot
                          ><slot name="callout-content"></slot>`
                    : ''}
                <slot name="body-xs"></slot>
                ${this.promoBottom
                    ? html`<slot name="promo-text"></slot
                          ><slot name="callout-content"></slot>`
                    : ''}
            </div>
            ${this.secureLabelFooter}
            <slot></slot>`;
    }

    getGlobalCSS() {
        return CSS;
    }

    dispatchActionMenuToggle = () => {
        this.card.dispatchEvent(
            new CustomEvent(EVENT_MERCH_CARD_ACTION_MENU_TOGGLE, {
                bubbles: true,
                composed: true,
                detail: {
                    card: this.card.name,
                    type: 'action-menu',
                },
            }),
        );
    };

    toggleActionMenu = (e) => {
        if (
            !this.actionMenuContentSlot ||
            !e ||
            (e.type !== 'click' && e.code !== 'Space' && e.code !== 'Enter')
        )
            return;

        e.preventDefault();
        e.stopPropagation();
        this.setMenuVisibility(!this.isMenuOpen());
    };

    toggleActionMenuFromCard = (e) => {
        //beware this is an event on card, so this points to the card, not the layout
        const retract = e?.type === 'mouseleave' ? true : undefined;
        this.card.blur();
        this.setIconVisibility(false);
        if (!this.actionMenuContentSlot) return;

        if (e?.type === 'mouseleave') {
            this.setMenuVisibility(false);
        }
    };

    showActionMenuOnHover = () => {
        if (!this.actionMenu) return;
        this.setIconVisibility(true);
    };

    hideActionMenu = () => {
        this.setMenuVisibility(false);
        this.setIconVisibility(false);
    };

    hideActionMenuOnBlur = (e) => {
        if (
            e.relatedTarget === this.actionMenu ||
            this.actionMenu?.contains(e.relatedTarget)
        )
            return;

        if (this.slottedContent?.contains(e.relatedTarget)) return;

        if (this.isMenuOpen()) {
            this.setMenuVisibility(false);
        }

        if (!this.card.contains(e.relatedTarget)) {
            this.setIconVisibility(false);
        }
    };

    handleCardFocusOut = (e) => {
        if (
            e.relatedTarget === this.actionMenu ||
            this.actionMenu?.contains(e.relatedTarget) ||
            e.relatedTarget === this.card
        ) {
            return;
        }

        if (
            this.slottedContent &&
            (e.target === this.slottedContent ||
                this.slottedContent.contains(e.target))
        ) {
            if (!this.slottedContent.contains(e.relatedTarget)) {
                this.setMenuVisibility(false);
            }
        }

        if (!this.card.contains(e.relatedTarget) && !this.isMenuOpen()) {
            this.setIconVisibility(false);
        }
    };

    handleKeyDown = (e) => {
        if (e.key === 'Escape' || e.key === 'Esc') {
            e.preventDefault();
            this.hideActionMenu();
            this.actionMenu?.focus();
        }
    };

    setAriaExpanded(element, value) {
        element.setAttribute('aria-expanded', value);
    }

    connectedCallbackHook() {
        this.card.addEventListener('mouseenter', this.showActionMenuOnHover);
        this.card.addEventListener('mouseleave', this.toggleActionMenuFromCard);
        this.card.addEventListener('focusin', this.showActionMenuOnHover);
        this.card.addEventListener('focusout', this.handleCardFocusOut);
        this.card.addEventListener('keydown', this.handleKeyDown);
    }

    disconnectedCallbackHook() {
        this.card.removeEventListener('mouseenter', this.showActionMenuOnHover);
        this.card.removeEventListener(
            'mouseleave',
            this.toggleActionMenuFromCard,
        );
        this.card.removeEventListener('focusin', this.showActionMenuOnHover);
        this.card.removeEventListener('focusout', this.handleCardFocusOut);
        this.card.removeEventListener('keydown', this.handleKeyDown);
    }

    static variantStyle = css`
        :host([variant='catalog']) {
            min-height: 330px;
            width: var(--consonant-merch-card-catalog-width);
        }

        .body .catalog-badge {
            display: flex;
            height: fit-content;
            flex-direction: column;
            width: fit-content;
            max-width: 140px;
            border-radius: 5px;
            position: relative;
            top: 0;
            margin-left: var(--consonant-merch-spacing-xxs);
            box-sizing: border-box;
        }

        :host([variant='catalog']) .action-menu:dir(rtl) {
            right: initial;
            left: 16px;
        }
    `;
}

import { html, css, LitElement, nothing } from 'lit';
import { MatchMediaController } from '@spectrum-web-components/reactive-controllers/src/MatchMedia.js';
import '../merch-search.js';
import './merch-sidenav-list.js';
import './merch-sidenav-checkbox-group.js';
import { SPECTRUM_MOBILE_LANDSCAPE, TABLET_DOWN } from '../media.js';
import { EVENT_MERCH_SIDENAV_SELECT } from '../constants.js';

const SEARCH_SIZE = {
    catalog: 'l',
};

const CHECKBOX_SIZE = {
    catalog: 'xl',
};

export class MerchSideNav extends LitElement {
    static properties = {
        sidenavTitle: { type: String },
        closeText: { type: String, attribute: 'close-text' },
        modal: { type: Boolean, reflect: true },
        open: { type: Boolean, state: true, reflect: true },
        autoclose: { type: Boolean, attribute: 'autoclose', reflect: true },
        dir: { type: String, state: true },
    };

    constructor() {
        super();
        this.open = false;
        this.autoclose = false;
        this.variant = null;
        this.dir = document.documentElement.dir || 'ltr';
        this.closeModal = this.closeModal.bind(this);
        this.handleSelection = this.handleSelection.bind(this);
    }

    connectedCallback() {
        super.connectedCallback();
        this.addEventListener(EVENT_MERCH_SIDENAV_SELECT, this.handleSelection);
        // Observe document direction changes
        this.dirObserver = new MutationObserver(() => {
            const newDir = document.documentElement.dir || 'ltr';
            if (this.dir !== newDir) {
                this.dir = newDir;
                this.requestUpdate();
            }
        });
        this.dirObserver.observe(document.documentElement, {
            attributes: true,
            attributeFilter: ['dir'],
        });
    }

    disconnectedCallback() {
        this.dirObserver?.disconnect();
        super.disconnectedCallback();
        this.removeEventListener(
            EVENT_MERCH_SIDENAV_SELECT,
            this.handleSelection,
        );
    }

    firstUpdated() {
        /* Adjust search size */
        const searchSize = SEARCH_SIZE[this.variant];
        if (searchSize) {
            const search = this.querySelector('merch-search sp-search');
            if (search) {
                search?.setAttribute('size', searchSize);
            }
        }

        /* Adjust checkboxes size */
        const checkboxSize = CHECKBOX_SIZE[this.variant];
        if (checkboxSize) {
            const checkboxes = this.querySelectorAll(
                'merch-sidenav-checkbox-group sp-checkbox',
            );
            checkboxes.forEach((checkbox) => {
                checkbox.setAttribute('size', checkboxSize);
            });
        }
    }

    updated() {
        if (this.mobileAndTablet.matches) {
            this.modal = true;
            this.style.padding = 0;
            this.style.margin = 0;
        } else {
            this.modal = false;
            this.style.removeProperty('padding');
            this.style.removeProperty('margin');
            if (this.open) this.closeModal();
        }
    }

    mobileDevice = new MatchMediaController(this, SPECTRUM_MOBILE_LANDSCAPE);
    mobileAndTablet = new MatchMediaController(this, TABLET_DOWN);

    get filters() {
        return this.querySelector('merch-sidenav-list');
    }

    get search() {
        return this.querySelector('merch-search');
    }

    render() {
        return this.mobileAndTablet.matches ? this.asDialog : this.asAside;
    }

    get asDialog() {
        if (!this.open) return nothing;
        const closeButton = !this.autoclose
            ? html`<sp-link @click="${this.closeModal}"
                  >${this.closeText || 'Close'}</sp-link
              >`
            : nothing;
        return html`
            <sp-theme color="light" scale="medium" dir="${this.dir}">
                <sp-overlay type="modal" open @sp-closed=${this.closeModal}>
                    <sp-dialog-base
                        dismissable
                        underlay
                        no-divider
                        @close=${this.closeModal}
                    >
                        <div id="content">
                            <div id="sidenav">
                                <div>
                                    <h2>${this.sidenavTitle}</h2>
                                    <slot></slot>
                                </div>
                                ${closeButton}
                            </div>
                        </div>
                    </sp-dialog-base>
                </sp-overlay>
            </sp-theme>
        `;
    }

    get asAside() {
        return html`<sp-theme color="light" scale="medium" dir="${this.dir}"
            ><h2>${this.sidenavTitle}</h2>
            <slot></slot
        ></sp-theme>`;
    }

    get dialog() {
        return this.shadowRoot.querySelector('sp-dialog-base');
    }

    handleSelection() {
        if (this.autoclose) this.closeModal();
    }

    closeModal() {
        this.open = false;
        document.querySelector('body')?.classList.remove('merch-modal');
    }

    showModal() {
        this.open = true;
        document.querySelector('body')?.classList.add('merch-modal');
    }

    static styles = css`
        :host {
            --merch-sidenav-padding: 16px;
            --merch-sidenav-collection-gap: 30px;
            /* Title */
            --merch-sidenav-title-font-size: 12px;
            --merch-sidenav-title-font-weight: 400;
            --merch-sidenav-title-line-height: 16px;
            --merch-sidenav-title-color: var(--spectrum-gray-700, #464646);
            --merch-sidenav-title-padding: 6px 12px 16px;
            /* Search */
            --merch-sidenav-search-gap: 10px;
            /* List */
            --merch-sidenav-list-gap: 0;
            --merch-sidenav-list-title-color: var(--spectrum-gray-700, #464646);
            --merch-sidenav-list-title-font-size: 14px;
            --merch-sidenav-list-title-font-weight: 400;
            --merch-sidenav-list-title-padding: 6px 12px 8px;
            --merch-sidenav-list-title-line-height: 18px;
            --merch-sidenav-item-height: unset;
            --merch-sidenav-item-inline-padding: 12px;
            --merch-sidenav-item-font-weight: 400;
            --merch-sidenav-item-font-size: 14px;
            --merch-sidenav-item-line-height: 18px;
            --merch-sidenav-item-label-top-margin: 6px;
            --merch-sidenav-item-label-bottom-margin: 8px;
            --merch-sidenav-item-icon-top-margin: 7px;
            --merch-sidenav-item-icon-gap: 8px;
            --merch-sidenav-item-selected-color: var(
                --spectrum-gray-800,
                #222222
            );
            --merch-sidenav-item-selected-background: var(
                --spectrum-gray-200,
                #e6e6e6
            );
            --merch-sidenav-list-item-gap: 4px;
            /* Checkbox group */
            --merch-sidenav-checkbox-group-title-font-size: 14px;
            --merch-sidenav-checkbox-group-title-font-weight: 400;
            --merch-sidenav-checkbox-group-title-line-height: 18px;
            --merch-sidenav-checkbox-group-title-color: var(
                --spectrum-gray-700,
                #464646
            );
            --merch-sidenav-checkbox-group-title-padding: 6px 0 8px;
            --merch-sidenav-checkbox-group-gap: 32px;
            --merch-sidenav-checkbox-group-padding: 0 12px;
            --merch-sidenav-checkbox-group-label-font-size: 17px;
            --merch-sidenav-checkbox-group-checkbox-spacing: 22px;
            --merch-sidenav-checkbox-group-label-gap: 13px;
            --merch-sidenav-checkbox-group-label-top-margin: 8px;
            --merch-sidenav-checkbox-group-height: 40px;
            /* Modal */
            --merch-sidenav-modal-close-font-size: 15px;
            --merch-sidenav-modal-close-line-height: 19px;
            --merch-sidenav-modal-close-gap: 10px;
            --merch-sidenav-modal-border-radius: 8px;
            --merch-sidenav-modal-padding: var(--merch-sidenav-padding);

            display: block;
            z-index: 2;
            padding: var(--merch-sidenav-padding);
            margin-inline-end: var(--merch-sidenav-collection-gap);
        }

        ::slotted(merch-sidenav-list) {
            --mod-sidenav-min-height: var(--merch-sidenav-item-height);
            --mod-sidenav-inline-padding: var(
                --merch-sidenav-item-inline-padding
            );
            --mod-sidenav-top-level-font-weight: var(
                --merch-sidenav-item-font-weight
            );
            --mod-sidenav-top-level-font-size: var(
                --merch-sidenav-item-font-size
            );
            --mod-sidenav-top-level-line-height: var(
                --merch-sidenav-item-line-height
            );
            --mod-sidenav-top-to-label: var(
                --merch-sidenav-item-label-top-margin
            );
            --mod-sidenav-bottom-to-label: var(
                --merch-sidenav-item-label-bottom-margin
            );
            --mod-sidenav-top-to-icon: var(
                --merch-sidenav-item-icon-top-margin
            );
            --mod-sidenav-icon-spacing: var(--merch-sidenav-item-icon-gap);
            --mod-sidenav-content-color-default-selected: var(
                --merch-sidenav-item-selected-color
            );
            --mod-sidenav-item-background-default-selected: var(
                --merch-sidenav-item-selected-background
            );
            --mod-sidenav-gap: var(--merch-sidenav-list-item-gap);
        }

        ::slotted(merch-sidenav-checkbox-group) {
            --mod-checkbox-font-size: var(
                --merch-sidenav-checkbox-group-label-font-size
            );
            --mod-checkbox-spacing: var(
                --merch-sidenav-checkbox-group-checkbox-spacing
            );
            --mod-checkbox-text-to-control: var(
                --merch-sidenav-checkbox-group-label-gap
            );
            --mod-checkbox-top-to-text: var(
                --merch-sidenav-checkbox-group-label-top-margin
            );
            --mod-checkbox-height: var(--merch-sidenav-checkbox-group-height);
        }

        :host h2 {
            color: var(--merch-sidenav-title-color);
            font-size: var(--merch-sidenav-title-font-size);
            font-weight: var(--merch-sidenav-title-font-weight);
            padding: var(--merch-sidenav-title-padding);
            line-height: var(--merch-sidenav-title-line-height);
            margin: 0;
            text-align: start;
        }

        :host-context([dir='rtl']) h2 {
            text-align: right;
        }

        :host(:dir(rtl)) h2 {
            text-align: right;
        }

        #content {
            width: 100%;
            height: 100%;
            display: flex;
            justify-content: center;
            align-items: baseline;
        }

        ::slotted(merch-search) {
            display: block;
            margin-bottom: var(--merch-sidenav-search-gap);
        }

        :host([modal]) ::slotted(merch-search) {
            display: none;
        }

        #sidenav {
            display: flex;
            flex-direction: column;
            max-width: 248px;
            overflow-y: auto;
            place-items: center;
            position: relative;
            width: 100%;
            border-radius: var(--merch-sidenav-modal-border-radius);
            padding: var(--merch-sidenav-modal-padding);
        }

        sp-dialog-base {
            --mod-modal-confirm-border-radius: var(
                --merch-sidenav-modal-border-radius
            );
            --mod-modal-max-height: 100dvh;
        }

        sp-dialog-base #sidenav {
            box-sizing: border-box;
            max-width: 300px;
            max-height: 95dvh;
            background: #ffffff 0% 0% no-repeat padding-box;
            box-shadow: 0px 1px 4px #00000026;
        }

        :host(:not([autoclose])) #sidenav h2 {
            margin-top: calc(
                var(--merch-sidenav-modal-close-gap) +
                    var(--merch-sidenav-modal-close-line-height)
            );
        }

        sp-link {
            position: absolute;
            top: 16px;
            inset-inline-end: 16px;
            font-size: var(--merch-sidenav-modal-close-font-size);
            line-height: var(--merch-sidenav-modal-close-line-height);
        }
    `;
}

customElements.define('merch-sidenav', MerchSideNav);

import { html, LitElement, css, nothing } from 'lit';
import { deeplink, pushStateFromComponent } from '../deeplink.js';
import { debounce, updateHash, paramsToHash } from '../utils.js';
import { EVENT_MERCH_SIDENAV_SELECT } from '../constants.js';

export class MerchSidenavList extends LitElement {
    static properties = {
        sidenavListTitle: { type: String },
        label: { type: String },
        deeplink: { type: String, attribute: 'deeplink' },
        selectedText: {
            type: String,
            reflect: true,
            attribute: 'selected-text',
        },
        selectedValue: {
            type: String,
            reflect: true,
            attribute: 'selected-value',
        },
        toggleIconColor: {
            type: Boolean,
            attribute: 'toggle-icon-color',
        },
    };

    static styles = css`
        :host {
            display: block;
            contain: content;
            margin-top: var(--merch-sidenav-list-gap);
        }

        :host h2 {
            color: var(--merch-sidenav-list-title-color);
            font-size: var(--merch-sidenav-list-title-font-size);
            font-weight: var(--merch-sidenav-list-title-font-weight);
            padding: var(--merch-sidenav-list-title-padding);
            line-height: var(--merch-sidenav-list-title-line-height);
            margin: 0;
            text-transform: uppercase;
        }

        :host(:dir(rtl)) h2 {
            text-align: right;
        }

        .right {
            position: absolute;
            inset-inline-end: 0;
        }

        :host(:dir(rtl)) .right {
            right: initial;
            left: 0;
        }
    `;

    constructor() {
        super();
        this.toggleIconColor = false;
        this.handleClickDebounced = debounce(this.handleClick.bind(this));
    }

    selectElement(element, selected = true) {
        element.selected = selected;
        if (element.parentNode.tagName === 'SP-SIDENAV-ITEM') {
            this.selectElement(element.parentNode, false);
        }
        const selectionElement = element.querySelector('.selection');
        selectionElement?.setAttribute('selected', selected);
        const selection = selectionElement?.dataset;
        const iconSrc =
            selected && this.toggleIconColor
                ? selection?.light
                : selection?.dark;
        if (iconSrc) {
            element.querySelector('img')?.setAttribute('src', iconSrc);
        }
        if (selected) {
            this.selectedElement = element;
            this.selectedText = selection?.selectedText || element.label;
            this.selectedValue = element.value;
            setTimeout(() => {
                element.selected = true;
            }, 1);
            this.dispatchEvent(
                new CustomEvent(EVENT_MERCH_SIDENAV_SELECT, {
                    bubbles: true,
                    composed: true,
                    detail: {
                        type: 'sidenav',
                        value: this.selectedValue,
                        elt: this.selectedElement,
                    },
                }),
            );
        }
    }

    markCurrentItem(element) {
        const sidenav = element.closest('sp-sidenav');
        if (!sidenav) return;
        sidenav
            .querySelectorAll('sp-sidenav-item[aria-current]')
            .forEach((currentItem) => {
                currentItem.removeAttribute('aria-current');
            });
        element.setAttribute('aria-current', 'true');
    }

    /**
     * click handler to manage first level items state of sidenav
     * @param {*} param
     */
    handleClick({ target: item }, shouldUpdateHash = true) {
        const { value, parentNode } = item;
        this.selectElement(item);
        this.markCurrentItem(item);
        if (parentNode?.tagName === 'SP-SIDENAV') {
            //swc does not consider, in multilevel, first level as a potential selection
            //and does not close other parents, we'll do that here
            parentNode
                .querySelectorAll(
                    'sp-sidenav-item[expanded],sp-sidenav-item[selected]',
                )
                .forEach((item) => {
                    if (item.value !== value) {
                        item.expanded = false;
                        item.removeAttribute('aria-expanded');
                        this.selectElement(item, false);
                    }
                });
            //additional call to disable previous selection settings
            parentNode
                .querySelectorAll('.selection[selected=true]')
                .forEach((selection) => {
                    const item = selection.parentElement;
                    if (item.value !== value) {
                        this.selectElement(item, false);
                    }
                });
        } else if (parentNode?.tagName === 'SP-SIDENAV-ITEM') {
            const topLevelItems = parentNode
                .closest('sp-sidenav')
                ?.querySelectorAll(':scope > sp-sidenav-item');
            [...topLevelItems]
                .filter((item) => item !== parentNode)
                .forEach((item) => {
                    item.expanded = false;
                    item.removeAttribute('aria-expanded');
                });
            parentNode
                .closest('sp-sidenav')
                ?.querySelectorAll('sp-sidenav-item[selected]')
                .forEach((item) => {
                    if (item.value !== value) {
                        this.selectElement(item, false);
                    }
                });
        }
        if (shouldUpdateHash) {
            pushStateFromComponent(this, value);
        }
    }

